import sys
import heapq

def main():
    import sys
    import heapq

    def read_ints():
        return list(map(int, sys.stdin.readline().split()))

    n, c = read_ints()
    a = read_ints()

    def calculate_value(arr, c):
        if len(arr) == 0:
            return 0
        arr.sort()
        k = len(arr)
        return sum(arr) - sum(arr[:k // c])

    min_sum = float('inf')
    current_sum = 0
    current_partition = []

    for i in range(n):
        current_partition.append(a[i])
        current_sum += a[i]

        if i == n - 1 or len(current_partition) >= c:
            value = calculate_value(current_partition, c)
            min_sum = min(min_sum, current_sum - value)
            current_partition = []
            current_sum = 0

    print(min_sum)

if __name__ == "__main__":
    main()

